#!/usr/bin/env python3
import sys
#sys.setrecursionlimit(150000)
from math import gcd

mm=[[[0]*200 for i in range(200)] for j in range(200)]

def d(a,b,c):
    return gcd(gcd(a+1,b+1),c+1)

def solve(K: int):
    ans=0
    a=[0,0,0]
    for i in range(K):
        for j in range(K):
            for k in range(K):
                ans+=d(i,j,k)
                continue
    print(ans)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    K = int(next(tokens))  # type: int
    solve(K)

if __name__ == '__main__':
    main()
